414 |   function _getKValue(uint32 marketIndex) internal view virtual returns (uint256) {
415 |     // Parameters controlling the float issuance multiplier.
416 |     (uint256 kPeriod, uint256 kInitialMultiplier) = _getMarketLaunchIncentiveParameters(marketIndex);
417 | 
418 |     // Sanity check - under normal circumstances, the multipliers should
419 |     // *never* be set to a value < 1e18, as there are guards against this.
420 |     assert(kInitialMultiplier >= 1e18);
421 | 
422 |     uint256 initialTimestamp = accumulativeFloatPerSyntheticTokenSnapshots[marketIndex][0].timestamp;
423 | 
424 |     if (block.timestamp - initialTimestamp <= kPeriod) {
425 |       return kInitialMultiplier - (((kInitialMultiplier - 1e18) * (block.timestamp - initialTimestamp)) / kPeriod);
426 |     } else {
427 |       return 1e18;
428 |     }
429 |   }
